//! 📌️ Annotation variants, appearances, markup and ordered geometric coordinates.
use super::*;

#[derive(Clone,Copy)]
#[repr(usize)]
enum O { State=2,StateModel,Action,Destination,Highlight,DefaultAppearance,Quadding,LineEnding,RichText,EndingStart,EndingEnd,LeaderLength,Caption,Icon,Symbol,ParentHigh,ParentLow,Open,File,Sound,Title,Movie,Activation,Field,Characteristics,AdditionalActions,MarkStyle,Colorants,Entries,FixedPrint,OverlayText,Repeat,Subtype,InteriorPresent,CalloutPresent,Point0,Point1,Point2,Point3 }
const WIDTH:usize=O::Point3 as usize+1;
fn put<'a>(cells:&mut[C<'a>],column:O,value:C<'a>){cells[column as usize-2]=value;}
fn wide(value:Option<u64>)->[C<'static>;2]{value.map_or([C::Null;2],|value|[C::Integer((value>>32)as i64),C::Integer((value&0xffff_ffff)as i64)])}
fn read_wide(row:Row<'_>,column:usize)->Result<Option<u64>,String>{match(optional_typed_integer::<u32>(row,column)?,optional_typed_integer::<u32>(row,column+1)?){(None,None)=>Ok(None),(Some(high),Some(low))=>Ok(Some((u64::from(high)<<32)|u64::from(low))),_=>Err("PDF wide index has an absent word".into())}}
fn write_reals(out:&mut Projection<'_,'_>,key:i64,role:&str,values:&[f64])->Result<(),String>{for(ordinal,value)in values.iter().enumerate(){out.insert("pdf_annotation_kind_real",&[C::Integer(key),C::Integer(ordinal as i64),C::Text(role),C::Real(*value)])?;}Ok(())}
fn read_reals(reader:&mut Reader<'_,'_,'_>,key:i64,role:&'static str)->Result<Vec<f64>,String>{let mut values=Vec::new();for row in reader.children_with_role("pdf_annotation_kind_real",1,2,key,Some((3,role)))?{let row=reader.take("pdf_annotation_kind_real",row.rowid,5)?;values.push(row.real(4)?);}Ok(values)}
fn read_optional_reals(reader:&mut Reader<'_,'_,'_>,row:Row<'_>,key:i64,column:O,role:&'static str)->Result<Option<Vec<f64>>,String>{if boolean(row,column as usize)?{read_reals(reader,key,role).map(Some)}else{Ok(None)}}
fn write_entry(out:&mut Projection<'_,'_>,entry:&PdfAppearanceEntry)->Result<i64,String>{let(kind,form)=match entry{PdfAppearanceEntry::Single{form}=>("single",C::Text(form)),PdfAppearanceEntry::States{..}=>("states",C::Null)};let key=out.insert("pdf_appearance_entry",&[C::Text(kind),form])?;if let PdfAppearanceEntry::States{states}=entry{for(ordinal,state)in states.iter().enumerate(){out.insert("pdf_appearance_state",&[C::Integer(key),C::Integer(ordinal as i64),C::Text(&state.state),C::Text(&state.form)])?;}}Ok(key)}
fn read_entry(reader:&mut Reader<'_,'_,'_>,key:i64)->Result<PdfAppearanceEntry,String>{let row=reader.take("pdf_appearance_entry",key,3)?;Ok(match row.text(1)?{"single"=>PdfAppearanceEntry::Single{form:reader.text(row,2)?},"states"=>{null_except(row,2..3,&[])?;let mut states=Vec::new();for child in reader.children("pdf_appearance_state",1,2,key)?{let child=reader.take("pdf_appearance_state",child.rowid,5)?;states.push(PdfAppearanceState{state:reader.text(child,3)?,form:reader.text(child,4)?});}PdfAppearanceEntry::States{states}},_=>return Err("unknown PDF appearance entry kind".into())})}
fn write_appearance(out:&mut Projection<'_,'_>,value:&PdfAppearance)->Result<i64,String>{let normal=write_entry(out,&value.normal)?;let rollover=value.rollover.as_ref().map(|value|write_entry(out,value)).transpose()?;let down=value.down.as_ref().map(|value|write_entry(out,value)).transpose()?;out.insert("pdf_appearance",&[C::Integer(normal),rollover.map_or(C::Null,C::Integer),down.map_or(C::Null,C::Integer)])}
fn read_appearance(reader:&mut Reader<'_,'_,'_>,key:i64)->Result<PdfAppearance,String>{let row=reader.take("pdf_appearance",key,4)?;Ok(PdfAppearance{normal:read_entry(reader,row.integer(1)?)?,rollover:optional_integer(row,2)?.map(|key|read_entry(reader,key)).transpose()?,down:optional_integer(row,3)?.map(|key|read_entry(reader,key)).transpose()?})}
fn write_border(out:&mut Projection<'_,'_>,value:&PdfBorderStyle)->Result<i64,String>{let mut cells=vec![C::Real(value.width),text_cell(&value.style),C::Integer(i64::from(value.dash.is_some()))];cells.extend(array_cells(&value.radii));let key=out.insert("pdf_annotation_border",&cells)?;if let Some(values)=&value.dash{write_sequence(out,"pdf_border_dash",key,values)?;}Ok(key)}
fn read_border(reader:&mut Reader<'_,'_,'_>,key:i64)->Result<PdfBorderStyle,String>{let row=reader.take("pdf_annotation_border",key,6)?;Ok(PdfBorderStyle{width:row.real(1)?,style:reader.optional_text(row,2)?,dash:if boolean(row,3)?{Some(read_sequence(reader,"pdf_border_dash",key)?)}else{None},radii:optional_array(row,4)?})}
fn write_markup(out:&mut Projection<'_,'_>,value:&PdfMarkupAnnotation)->Result<i64,String>{let date=value.creation_date.as_ref().map(|value|metadata::write_date(out,value)).transpose()?;let mut cells=vec![text_cell(&value.title)];cells.extend(wide(value.popup));cells.extend([real_cell(value.opacity),text_cell(&value.rich_contents),date.map_or(C::Null,C::Integer)]);cells.extend(wide(value.in_reply_to));cells.extend([text_cell(&value.subject),text_cell(&value.reply_type),text_cell(&value.intent)]);out.insert("pdf_annotation_markup",&cells)}
fn read_markup(reader:&mut Reader<'_,'_,'_>,key:i64)->Result<PdfMarkupAnnotation,String>{let row=reader.take("pdf_annotation_markup",key,12)?;Ok(PdfMarkupAnnotation{title:reader.optional_text(row,1)?,popup:read_wide(row,2)?,opacity:optional_real(row,4)?,rich_contents:reader.optional_text(row,5)?,creation_date:optional_integer(row,6)?.map(|key|metadata::read_date(reader,key)).transpose()?,in_reply_to:read_wide(row,7)?,subject:reader.optional_text(row,9)?,reply_type:reader.optional_text(row,10)?,intent:reader.optional_text(row,11)?})}

fn write_kind(out:&mut Projection<'_,'_>,value:&PdfAnnotationKind)->Result<i64,String>{
    let mut fields=[C::Null;WIDTH-2];let mut points=None;
    let kind=match value{
        PdfAnnotationKind::Text{open,icon,state,state_model}=>{put(&mut fields,O::Open,C::Integer(i64::from(*open)));put(&mut fields,O::Icon,text_cell(icon));put(&mut fields,O::State,text_cell(state));put(&mut fields,O::StateModel,text_cell(state_model));"text"},
        PdfAnnotationKind::Link{action,destination,highlight,..}=>{put(&mut fields,O::Action,action.as_ref().map(|value|navigation::write_action(out,value)).transpose()?.map_or(C::Null,C::Integer));put(&mut fields,O::Destination,destination.as_ref().map(|value|navigation::write_destination(out,value)).transpose()?.map_or(C::Null,C::Integer));put(&mut fields,O::Highlight,text_cell(highlight));"link"},
        PdfAnnotationKind::FreeText{default_appearance,quadding,callout,line_ending,rich_text}=>{put(&mut fields,O::DefaultAppearance,C::Text(default_appearance));put(&mut fields,O::Quadding,C::Integer(i64::from(*quadding)));put(&mut fields,O::CalloutPresent,C::Integer(i64::from(callout.is_some())));put(&mut fields,O::LineEnding,text_cell(line_ending));put(&mut fields,O::RichText,text_cell(rich_text));"freeText"},
        PdfAnnotationKind::Line{points:coordinates,line_endings,interior_color,leader_length,caption}=>{points=Some(*coordinates);if let Some(endings)=line_endings{put(&mut fields,O::EndingStart,C::Text(&endings[0]));put(&mut fields,O::EndingEnd,C::Text(&endings[1]));}put(&mut fields,O::InteriorPresent,C::Integer(i64::from(interior_color.is_some())));put(&mut fields,O::LeaderLength,real_cell(*leader_length));put(&mut fields,O::Caption,C::Integer(i64::from(*caption)));"line"},
        PdfAnnotationKind::Square{interior_color,rect_differences}|PdfAnnotationKind::Circle{interior_color,rect_differences}=>{points=*rect_differences;put(&mut fields,O::InteriorPresent,C::Integer(i64::from(interior_color.is_some())));if matches!(value,PdfAnnotationKind::Square{..}){"square"}else{"circle"}},
        PdfAnnotationKind::Polygon{interior_color,..}=>{put(&mut fields,O::InteriorPresent,C::Integer(i64::from(interior_color.is_some())));"polygon"},
        PdfAnnotationKind::PolyLine{line_endings,interior_color,..}=>{if let Some(endings)=line_endings{put(&mut fields,O::EndingStart,C::Text(&endings[0]));put(&mut fields,O::EndingEnd,C::Text(&endings[1]));}put(&mut fields,O::InteriorPresent,C::Integer(i64::from(interior_color.is_some())));"polyLine"},
        PdfAnnotationKind::Highlight{..}=>"highlight",PdfAnnotationKind::Underline{..}=>"underline",PdfAnnotationKind::Squiggly{..}=>"squiggly",PdfAnnotationKind::StrikeOut{..}=>"strikeOut",
        PdfAnnotationKind::Stamp{icon}=>{put(&mut fields,O::Icon,text_cell(icon));"stamp"},PdfAnnotationKind::Caret{rect_differences,symbol}=>{points=*rect_differences;put(&mut fields,O::Symbol,text_cell(symbol));"caret"},PdfAnnotationKind::Ink{..}=>"ink",
        PdfAnnotationKind::Popup{parent,open}=>{let words=wide(*parent);put(&mut fields,O::ParentHigh,words[0]);put(&mut fields,O::ParentLow,words[1]);put(&mut fields,O::Open,C::Integer(i64::from(*open)));"popup"},
        PdfAnnotationKind::FileAttachment{file,icon}=>{put(&mut fields,O::File,C::Integer(navigation::write_file_spec(out,file)?));put(&mut fields,O::Icon,text_cell(icon));"fileAttachment"},
        PdfAnnotationKind::Sound{sound,icon}=>{put(&mut fields,O::Sound,C::Integer(cos::write_dictionary(out,sound)?));put(&mut fields,O::Icon,text_cell(icon));"sound"},
        PdfAnnotationKind::Movie{title,movie,activation}=>{put(&mut fields,O::Title,text_cell(title));put(&mut fields,O::Movie,C::Integer(cos::write_dictionary(out,movie)?));put(&mut fields,O::Activation,activation.as_ref().map(|value|cos::write_dictionary(out,value)).transpose()?.map_or(C::Null,C::Integer));"movie"},
        PdfAnnotationKind::Widget{field,highlight,characteristics,action,additional_actions}=>{put(&mut fields,O::Field,text_cell(field));put(&mut fields,O::Highlight,text_cell(highlight));put(&mut fields,O::Characteristics,C::Integer(cos::write_dictionary(out,characteristics)?));put(&mut fields,O::Action,action.as_ref().map(|value|navigation::write_action(out,value)).transpose()?.map_or(C::Null,C::Integer));put(&mut fields,O::AdditionalActions,C::Integer(cos::write_dictionary(out,additional_actions)?));"widget"},
        PdfAnnotationKind::Screen{title,characteristics,action,additional_actions}=>{put(&mut fields,O::Title,text_cell(title));put(&mut fields,O::Characteristics,C::Integer(cos::write_dictionary(out,characteristics)?));put(&mut fields,O::Action,action.as_ref().map(|value|navigation::write_action(out,value)).transpose()?.map_or(C::Null,C::Integer));put(&mut fields,O::AdditionalActions,C::Integer(cos::write_dictionary(out,additional_actions)?));"screen"},
        PdfAnnotationKind::PrinterMark{mark_style,colorants}=>{put(&mut fields,O::MarkStyle,text_cell(mark_style));put(&mut fields,O::Colorants,C::Integer(cos::write_dictionary(out,colorants)?));"printerMark"},
        PdfAnnotationKind::TrapNet{entries}|PdfAnnotationKind::ThreeD{entries}=>{put(&mut fields,O::Entries,C::Integer(cos::write_dictionary(out,entries)?));if matches!(value,PdfAnnotationKind::TrapNet{..}){"trapNet"}else{"threeD"}},
        PdfAnnotationKind::Watermark{fixed_print}=>{put(&mut fields,O::FixedPrint,fixed_print.as_ref().map(|value|cos::write_dictionary(out,value)).transpose()?.map_or(C::Null,C::Integer));"watermark"},
        PdfAnnotationKind::Redact{interior_color,overlay_text,repeat,default_appearance,quadding,..}=>{put(&mut fields,O::InteriorPresent,C::Integer(i64::from(interior_color.is_some())));put(&mut fields,O::OverlayText,text_cell(overlay_text));put(&mut fields,O::Repeat,C::Integer(i64::from(*repeat)));put(&mut fields,O::DefaultAppearance,text_cell(default_appearance));put(&mut fields,O::Quadding,C::Integer(i64::from(*quadding)));"redact"},
        PdfAnnotationKind::Unknown{subtype,entries}=>{put(&mut fields,O::Subtype,C::Text(subtype));put(&mut fields,O::Entries,C::Integer(cos::write_dictionary(out,entries)?));"unknown"},
    };
    if let Some(points)=points{for(index,value)in points.iter().enumerate(){fields[O::Point0 as usize-2+index]=C::Real(*value);}}
    let mut cells=vec![C::Text(kind)];cells.extend(fields);let key=out.insert("pdf_annotation_detail",&cells)?;
    match value{
        PdfAnnotationKind::Link{quad_points,..}|PdfAnnotationKind::Highlight{quad_points}|PdfAnnotationKind::Underline{quad_points}|PdfAnnotationKind::Squiggly{quad_points}|PdfAnnotationKind::StrikeOut{quad_points}|PdfAnnotationKind::Redact{quad_points,..}=>write_reals(out,key,"quad",quad_points)?,
        PdfAnnotationKind::Polygon{vertices,..}|PdfAnnotationKind::PolyLine{vertices,..}=>write_reals(out,key,"vertices",vertices)?,
        PdfAnnotationKind::FreeText{callout:Some(values),..}=>write_reals(out,key,"callout",values)?,
        PdfAnnotationKind::Ink{paths}=>{for(ordinal,path)in paths.iter().enumerate(){let path_key=out.insert("pdf_annotation_ink_path",&[C::Integer(key),C::Integer(ordinal as i64)])?;write_sequence(out,"pdf_annotation_ink_coordinate",path_key,path)?;}},_=>{}
    }
    match value{PdfAnnotationKind::Line{interior_color:Some(values),..}|PdfAnnotationKind::Square{interior_color:Some(values),..}|PdfAnnotationKind::Circle{interior_color:Some(values),..}|PdfAnnotationKind::Polygon{interior_color:Some(values),..}|PdfAnnotationKind::PolyLine{interior_color:Some(values),..}|PdfAnnotationKind::Redact{interior_color:Some(values),..}=>write_reals(out,key,"interior",values)?,_=>{}}
    Ok(key)
}
fn read_endings(reader:&mut Reader<'_ ,'_ ,'_>,row:Row<'_>)->Result<Option<[String;2]>,String>{match(row.optional_text(O::EndingStart as usize)?,row.optional_text(O::EndingEnd as usize)?){(None,None)=>Ok(None),(Some(start),Some(end))=>Ok(Some([reader.copy_text(start)?,reader.copy_text(end)?])),_=>Err("PDF line endings must both exist".into())}}
fn read_kind(reader:&mut Reader<'_,'_,'_>,key:i64)->Result<PdfAnnotationKind,String>{
    let row=reader.take("pdf_annotation_detail",key,WIDTH)?;
    let(value,present):(PdfAnnotationKind,&[O])=match row.text(1)?{
        "text"=>(PdfAnnotationKind::Text{open:boolean(row,O::Open as usize)?,icon:reader.optional_text(row,O::Icon as usize)?,state:reader.optional_text(row,O::State as usize)?,state_model:reader.optional_text(row,O::StateModel as usize)?},&[O::Open,O::Icon,O::State,O::StateModel]),
        "link"=>(PdfAnnotationKind::Link{action:optional_integer(row,O::Action as usize)?.map(|key|navigation::read_action(reader,key)).transpose()?,destination:optional_integer(row,O::Destination as usize)?.map(|key|navigation::read_destination(reader,key)).transpose()?,highlight:reader.optional_text(row,O::Highlight as usize)?,quad_points:read_reals(reader,key,"quad")?},&[O::Action,O::Destination,O::Highlight]),
        "freeText"=>(PdfAnnotationKind::FreeText{default_appearance:reader.text(row,O::DefaultAppearance as usize)?,quadding:integer(row,O::Quadding as usize)?,callout:read_optional_reals(reader,row,key,O::CalloutPresent,"callout")?,line_ending:reader.optional_text(row,O::LineEnding as usize)?,rich_text:reader.optional_text(row,O::RichText as usize)?},&[O::DefaultAppearance,O::Quadding,O::CalloutPresent,O::LineEnding,O::RichText]),
        "line"=>(PdfAnnotationKind::Line{points:optional_array(row,O::Point0 as usize)?.ok_or("missing PDF line coordinates")?,line_endings:read_endings(reader,row)?,interior_color:read_optional_reals(reader,row,key,O::InteriorPresent,"interior")?,leader_length:optional_real(row,O::LeaderLength as usize)?,caption:boolean(row,O::Caption as usize)?},&[O::Point0,O::Point1,O::Point2,O::Point3,O::EndingStart,O::EndingEnd,O::InteriorPresent,O::LeaderLength,O::Caption]),
        "square"=>(PdfAnnotationKind::Square{interior_color:read_optional_reals(reader,row,key,O::InteriorPresent,"interior")?,rect_differences:optional_array(row,O::Point0 as usize)?},&[O::InteriorPresent,O::Point0,O::Point1,O::Point2,O::Point3]),
        "circle"=>(PdfAnnotationKind::Circle{interior_color:read_optional_reals(reader,row,key,O::InteriorPresent,"interior")?,rect_differences:optional_array(row,O::Point0 as usize)?},&[O::InteriorPresent,O::Point0,O::Point1,O::Point2,O::Point3]),
        "polygon"=>(PdfAnnotationKind::Polygon{vertices:read_reals(reader,key,"vertices")?,interior_color:read_optional_reals(reader,row,key,O::InteriorPresent,"interior")?},&[O::InteriorPresent]),
        "polyLine"=>(PdfAnnotationKind::PolyLine{vertices:read_reals(reader,key,"vertices")?,line_endings:read_endings(reader,row)?,interior_color:read_optional_reals(reader,row,key,O::InteriorPresent,"interior")?},&[O::EndingStart,O::EndingEnd,O::InteriorPresent]),
        "highlight"=>(PdfAnnotationKind::Highlight{quad_points:read_reals(reader,key,"quad")?},&[]),"underline"=>(PdfAnnotationKind::Underline{quad_points:read_reals(reader,key,"quad")?},&[]),"squiggly"=>(PdfAnnotationKind::Squiggly{quad_points:read_reals(reader,key,"quad")?},&[]),"strikeOut"=>(PdfAnnotationKind::StrikeOut{quad_points:read_reals(reader,key,"quad")?},&[]),
        "stamp"=>(PdfAnnotationKind::Stamp{icon:reader.optional_text(row,O::Icon as usize)?},&[O::Icon]),"caret"=>(PdfAnnotationKind::Caret{rect_differences:optional_array(row,O::Point0 as usize)?,symbol:reader.optional_text(row,O::Symbol as usize)?},&[O::Point0,O::Point1,O::Point2,O::Point3,O::Symbol]),
        "ink"=>{let mut paths=Vec::new();for path in reader.children("pdf_annotation_ink_path",1,2,key)?{let path=reader.take("pdf_annotation_ink_path",path.rowid,3)?;paths.push(read_sequence(reader,"pdf_annotation_ink_coordinate",path.rowid)?);}(PdfAnnotationKind::Ink{paths},&[])},
        "popup"=>(PdfAnnotationKind::Popup{parent:read_wide(row,O::ParentHigh as usize)?,open:boolean(row,O::Open as usize)?},&[O::ParentHigh,O::ParentLow,O::Open]),
        "fileAttachment"=>(PdfAnnotationKind::FileAttachment{file:navigation::read_file_spec(reader,row.integer(O::File as usize)?)?,icon:reader.optional_text(row,O::Icon as usize)?},&[O::File,O::Icon]),
        "sound"=>(PdfAnnotationKind::Sound{sound:cos::read_dictionary(reader,row.integer(O::Sound as usize)?)?,icon:reader.optional_text(row,O::Icon as usize)?},&[O::Sound,O::Icon]),
        "movie"=>(PdfAnnotationKind::Movie{title:reader.optional_text(row,O::Title as usize)?,movie:cos::read_dictionary(reader,row.integer(O::Movie as usize)?)?,activation:optional_integer(row,O::Activation as usize)?.map(|key|cos::read_dictionary(reader,key)).transpose()?},&[O::Title,O::Movie,O::Activation]),
        "widget"=>(PdfAnnotationKind::Widget{field:reader.optional_text(row,O::Field as usize)?,highlight:reader.optional_text(row,O::Highlight as usize)?,characteristics:cos::read_dictionary(reader,row.integer(O::Characteristics as usize)?)?,action:optional_integer(row,O::Action as usize)?.map(|key|navigation::read_action(reader,key)).transpose()?,additional_actions:cos::read_dictionary(reader,row.integer(O::AdditionalActions as usize)?)?},&[O::Field,O::Highlight,O::Characteristics,O::Action,O::AdditionalActions]),
        "screen"=>(PdfAnnotationKind::Screen{title:reader.optional_text(row,O::Title as usize)?,characteristics:cos::read_dictionary(reader,row.integer(O::Characteristics as usize)?)?,action:optional_integer(row,O::Action as usize)?.map(|key|navigation::read_action(reader,key)).transpose()?,additional_actions:cos::read_dictionary(reader,row.integer(O::AdditionalActions as usize)?)?},&[O::Title,O::Characteristics,O::Action,O::AdditionalActions]),
        "printerMark"=>(PdfAnnotationKind::PrinterMark{mark_style:reader.optional_text(row,O::MarkStyle as usize)?,colorants:cos::read_dictionary(reader,row.integer(O::Colorants as usize)?)?},&[O::MarkStyle,O::Colorants]),
        "trapNet"=>(PdfAnnotationKind::TrapNet{entries:cos::read_dictionary(reader,row.integer(O::Entries as usize)?)?},&[O::Entries]),"threeD"=>(PdfAnnotationKind::ThreeD{entries:cos::read_dictionary(reader,row.integer(O::Entries as usize)?)?},&[O::Entries]),
        "watermark"=>(PdfAnnotationKind::Watermark{fixed_print:optional_integer(row,O::FixedPrint as usize)?.map(|key|cos::read_dictionary(reader,key)).transpose()?},&[O::FixedPrint]),
        "redact"=>(PdfAnnotationKind::Redact{quad_points:read_reals(reader,key,"quad")?,interior_color:read_optional_reals(reader,row,key,O::InteriorPresent,"interior")?,overlay_text:reader.optional_text(row,O::OverlayText as usize)?,repeat:boolean(row,O::Repeat as usize)?,default_appearance:reader.optional_text(row,O::DefaultAppearance as usize)?,quadding:integer(row,O::Quadding as usize)?},&[O::InteriorPresent,O::OverlayText,O::Repeat,O::DefaultAppearance,O::Quadding]),
        "unknown"=>(PdfAnnotationKind::Unknown{subtype:reader.text(row,O::Subtype as usize)?,entries:cos::read_dictionary(reader,row.integer(O::Entries as usize)?)?},&[O::Subtype,O::Entries]),_=>return Err("unknown PDF annotation kind".into()),
    };let columns=present.iter().map(|value|*value as usize).collect::<Vec<_>>();null_except(row,2..WIDTH,&columns)?;Ok(value)
}
pub(super) fn write_annotation(out:&mut Projection<'_,'_>,value:&PdfAnnotation)->Result<i64,String>{
    let border=value.border.as_ref().map(|value|write_border(out,value)).transpose()?;let appearance=value.appearance.as_ref().map(|value|write_appearance(out,value)).transpose()?;let markup=value.markup.as_ref().map(|value|write_markup(out,value)).transpose()?;let extra=cos::write_dictionary(out,&value.extra)?;let detail=write_kind(out,&value.kind)?;
    let mut cells=value.rect.map(C::Real).to_vec();cells.extend([text_cell(&value.contents),text_cell(&value.name),text_cell(&value.modified),C::Integer(i64::from(value.flags)),border.map_or(C::Null,C::Integer),appearance.map_or(C::Null,C::Integer),text_cell(&value.appearance_state),markup.map_or(C::Null,C::Integer),text_cell(&value.optional_content),integer_cell(value.struct_parent),C::Integer(extra),C::Integer(detail)]);let key=out.insert("pdf_annotation",&cells)?;write_sequence(out,"pdf_annotation_real",key,&value.color)?;Ok(key)
}
pub(super) fn read_annotation(reader:&mut Reader<'_,'_,'_>,key:i64)->Result<PdfAnnotation,String>{let row=reader.take("pdf_annotation",key,17)?;Ok(PdfAnnotation{rect:[row.real(1)?,row.real(2)?,row.real(3)?,row.real(4)?],kind:read_kind(reader,row.integer(16)?)?,contents:reader.optional_text(row,5)?,name:reader.optional_text(row,6)?,modified:reader.optional_text(row,7)?,flags:integer(row,8)?,border:optional_integer(row,9)?.map(|key|read_border(reader,key)).transpose()?,color:read_sequence(reader,"pdf_annotation_real",key)?,appearance:optional_integer(row,10)?.map(|key|read_appearance(reader,key)).transpose()?,appearance_state:reader.optional_text(row,11)?,markup:optional_integer(row,12)?.map(|key|read_markup(reader,key)).transpose()?,optional_content:reader.optional_text(row,13)?,struct_parent:optional_typed_integer(row,14)?,extra:cos::read_dictionary(reader,row.integer(15)?)?})}
